}

// src/routes.js — MỌI route khai báo ở một chỗ, dạng mảng object
import MainLayout from './layouts/MainLayout';
import Home from './pages/Home';
import BlogList from './pages/BlogList';
import BlogPost from './pages/BlogPost';
import NotFound from './pages/NotFound';

export const routes = [
  {
    path: '/',
    element: <MainLayout />,
    children: [
      { index: true, element: <Home /> },
      {
        path: 'blog',
        children: [
          { index: true, element: <BlogList /> },
          { path: ':slug', element: <BlogPost /> },
        ],
      },
      { path: '*', element: <NotFound /> },
    ],
  },
];

// src/layouts/MainLayout.js — header + nav dùng chung, trang con vẽ vào <Outlet />
import { NavLink, Outlet } from 'react-router-dom';

export default function MainLayout() {
  return (
    <div>
      <header id="site-header">
        <NavLink to="/" end id="nav-home">Home</NavLink>{' '}
        <NavLink to="/blog" id="nav-blog">Blog</NavLink>
      </header>
      <main id="main">
        <Outlet />
      </main>
    </div>
  );
}

